import {publicRoleName} from './profile-display.js';

const IDS=Array.from({length:20},(_,index)=>`SCNR-${String(index+1).padStart(3,'0')}`);
const TWELVE_HOURS=12*60*60*1000;
const ACTIONS={check_in:'Checked in',check_out:'Checked out',out_of_service:'Marked out of service',return_to_service:'Returned to service',update_location:'Location updated'};
const ACTION_TITLES={check_in:'Check in scanner',check_out:'Check out scanner',out_of_service:'Report out of service',return_to_service:'Return to service',update_location:'Update location'};
const pacificDateFormatter=new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'});
const stampFormatter=new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
const scannerGlyph=()=>'<svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><rect x="8" y="3" width="17" height="20" rx="4" fill="currentColor" opacity=".12"/><rect x="8" y="3" width="17" height="20" rx="4" stroke="currentColor" stroke-width="1.7"/><rect x="11" y="7" width="11" height="7" rx="1" stroke="currentColor" stroke-width="1.5"/><path d="M12 17h2m3 0h3M12 20h8M13 24l-3 5h7l3-5" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/><path d="M14 9v3m3-3v3m3-3v3" stroke="currentColor"/></svg>';
const stamp=value=>Number(value)>0?`${stampFormatter.format(new Date(Number(value)))} PT`:'No action recorded';
const pacificDate=value=>{if(!Number(value))return '';const parts=Object.fromEntries(pacificDateFormatter.formatToParts(new Date(Number(value))).map(part=>[part.type,part.value]));return `${parts.year}-${parts.month}-${parts.day}`;};
const duration=milliseconds=>{const minutes=Math.max(0,Math.floor(milliseconds/60000));if(minutes<1)return 'less than a minute';if(minutes<60)return `${minutes} min`;const hours=Math.floor(minutes/60);if(hours<24)return `${hours} ${hours===1?'hr':'hrs'}`;const days=Math.floor(hours/24),remaining=hours%24;return `${days} ${days===1?'day':'days'}${remaining?` ${remaining} hrs`:''}`;};
const ago=(timestamp,now)=>Number(timestamp)>0?`${duration(now-Number(timestamp))} ago`:'No previous action';
const eventTime=event=>Number(event.createdAt||event.updatedAt)||0;
const serviceEvent=event=>['out_of_service','return_to_service'].includes(event.action||event.lastAction)||((event.action||event.lastAction)==='check_in'&&event.condition==='out_of_service');

export function createScannerUI(context){
  const {getState,getPlatform,escape,icon,time,toast,dialog,requireUser,fitActionDialog,links,asset}=context;
  let view='board',selectedId=null,detailTab='activity',filter='all',search='',logScanner='',logPerson='',logAction='',logStart='',logEnd='',logLimit=50,detailLimit=50,destroyed=false;
  const drafts=new Map();
  let layout='grid';try{layout=localStorage.getItem('sujaTools.view.scanner')==='list'?'list':'grid';}catch{}
  const has=(state,permission)=>!!state.user&&(state.user.roleId==='master'||state.user.permissions?.includes(permission));
  const master=state=>state.user?.roleId==='master';
  const nowOf=state=>Number(state.now)||Date.now();
  const current=(state,id)=>state.scanners?.[id]||null;
  const inventory=(state,id)=>({id,label:id,homeLocation:'',...state.scannerInventory?.[id]});
  const history=(state,id)=>{const values=state.scannerHistory?.[id]||[];return (Array.isArray(values)?values:Object.values(values)).filter(Boolean).map(event=>({...event,scannerId:event.scannerId||id})).sort((a,b)=>eventTime(b)-eventTime(a));};
  const allHistory=state=>IDS.flatMap(id=>history(state,id)).sort((a,b)=>eventTime(b)-eventTime(a));
  const isOverdue=(state,device)=>device?.checkoutStatus==='checked_out'&&Number(device.checkedOutAt)>0&&nowOf(state)-Number(device.checkedOutAt)>TWELVE_HOURS;
  function facts(state,id){
    const device=current(state,id),meta=inventory(state,id),condition=device?.condition||'unconfirmed',checkout=device?.checkoutStatus||'unconfirmed';
    const status=condition==='out_of_service'?'service':checkout==='checked_out'?'out':checkout==='checked_in'&&condition==='good'?'available':'unconfirmed';
    return {id,device,meta,condition,checkout,status,overdue:isOverdue(state,device),holder:checkout==='checked_out'?device?.holderName||'Unknown person':device?.lastHolderName||'No checkout recorded',location:device?.location||meta.homeLocation||'Not yet recorded'};
  }
  function statusBadge(info){const labels={available:'Available',out:'Checked out',service:'Out of service',unconfirmed:'Unconfirmed'},extra=info.condition==='good'?'Good':info.condition==='out_of_service'?(info.checkout==='checked_out'?'Checked out':info.checkout==='checked_in'?'Checked in':'Custody unconfirmed'):'';return `<span class="scanner-badges"><span class="scanner-status scanner-status-${info.status}"><span class="dot"></span>${labels[info.status]}</span>${extra?`<span class="scanner-condition-note">${extra}</span>`:''}</span>`;}
  function roleLabel(person){if(!person)return '';if(person.roleId==='master')return publicRoleName(person.roleId,person.roleName);return (person.roleNames?.length?person.roleNames:[person.roleName||person.roleId]).filter(Boolean).join(', ');}
  function primaryAction(state,info){
    if(!has(state,'scanner.use')||state.scannerSetupRequired)return {type:'device',label:'View scanner'};
    if(info.status==='available')return {type:'check_out',label:'Check out'};
    if(info.checkout==='checked_out'&&(info.device?.holderUid===state.user.uid||has(state,'scanner.manage')))return {type:'check_in',label:'Check in'};
    if(info.checkout==='unconfirmed')return {type:'check_in',label:'Confirm check-in'};
    return {type:'device',label:'View scanner'};
  }
  const actionButton=(type,id,label,classes='btn secondary')=>`<button type="button" class="${classes}" data-scanner-action="${escape(type)}" data-scanner-id="${escape(id)}">${escape(label)}</button>`;
  function route(next,id=null){view=next;selectedId=IDS.includes(id)?id:null;detailLimit=50;const hash=next==='device'&&selectedId?`device=${encodeURIComponent(selectedId)}`:next==='log'?'log':next==='inventory'?'inventory':'';try{window.history.replaceState(null,'',`${window.location.pathname}${window.location.search}${hash?'#'+hash:''}`);}catch{}redraw();}
  function readRoute(){const hash=window.location.hash.slice(1);if(hash.startsWith('device=')){let id='';try{id=decodeURIComponent(hash.slice(7));}catch{}if(IDS.includes(id)){view='device';selectedId=id;return;}}view=hash==='log'?'log':hash==='inventory'?'inventory':'board';selectedId=null;}
  function redraw(){
    if(destroyed)return;const wrapper=document.getElementById('scanner-workspace');if(!wrapper)return;
    const focused=wrapper.contains(document.activeElement)?document.activeElement:null,field=focused?.dataset.scannerField,selection=focused?.selectionStart;
    wrapper.outerHTML=render(getState());afterRender(getState());
    if(field){const restored=document.querySelector(`#scanner-workspace [data-scanner-field="${field}"]`);restored?.focus({preventScroll:true});if(typeof selection==='number'&&restored?.setSelectionRange){try{restored.setSelectionRange(selection,selection);}catch{}}}
  }
  const tabs=state=>`<nav class="scanner-tabs" aria-label="Scanner pages"><button type="button" data-scanner-action="board" class="${view==='board'?'active':''}" aria-current="${view==='board'?'page':'false'}">Scanner board</button><button type="button" data-scanner-action="log" class="${view==='log'?'active':''}" aria-current="${view==='log'?'page':'false'}">Complete log</button>${master(state)?`<button type="button" data-scanner-action="inventory" class="${view==='inventory'?'active':''}" aria-current="${view==='inventory'?'page':'false'}">Manage fleet</button>`:''}</nav>`;
  function setupNotice(state){return state.scannerSetupRequired?'<div class="scanner-setup-note" role="status"><b>Scanner tracking is awaiting workspace setup.</b><span>Your administrator needs to activate the scanner workspace before equipment can be checked in or out.</span></div>':'';}
  function rolesNeedSetup(state){return master(state)&&['operator','manager','lead','supervisor','forklift_driver','netsuite_operator'].some(id=>!state.roles?.[id]?.permissions?.includes('scanner.use'));}
  function heading(state){return `<div class="scanner-heading"><div><span class="eyebrow">Equipment / Team accountability</span><h1>Suja Scanner Status</h1><p>Check it out. Bring it back. Keep the history clear.</p></div><span class="live-indicator"><span class="dot"></span>${!state.user?'Sign in to view scanners':state.scannerSetupRequired?'Setup needed':state.connected?'Live equipment log':'Reconnecting'}</span></div>`;}
  function gate(state){return `<section class="scanner-gate card"><div><span class="eyebrow">SCNR-001 through SCNR-020</span><h2>Your scanner. Your shift. One clear record.</h2><p>Check equipment in or out with your Suja account. See who has each scanner, its condition, location, and complete history.</p><button type="button" class="btn" data-scanner-action="signin">${state.account?'View account':'Sign in'} ${icon('arrow')}</button></div><img src="${escape(asset('scanner-app.svg'))}" alt="Handheld scanner with check-in and checkout symbols"></section>`;}
  function card(state,id){
    const info=facts(state,id),action=primaryAction(state,info),last=info.device?.lastCustodyAt,now=nowOf(state);
    return `<article class="scanner-card card ${info.overdue?'scanner-overdue':''}" data-scanner-card="${id}"><button type="button" class="scanner-card-title" data-scanner-action="device" data-scanner-id="${id}" aria-label="View ${escape(info.meta.label)}"><span class="scanner-glyph">${scannerGlyph()}</span><span><strong>${escape(info.meta.label)}</strong>${info.meta.label!==id?`<small>${id}</small>`:''}</span>${icon('arrow')}</button><div class="scanner-card-flags">${statusBadge(info)}${info.overdue?'<span class="scanner-overdue-badge">Over 12 hrs</span>':''}</div><dl class="scanner-card-facts"><div><dt>${info.checkout==='checked_out'?'With':'Last with'}</dt><dd>${escape(info.holder)}</dd></div><div><dt>Location</dt><dd>${escape(info.location)}</dd></div><div class="scanner-card-action-time"><dt>${last?ACTIONS[info.device.lastCustodyAction]||'Last custody action':'Last custody action'}</dt><dd>${last?`<time datetime="${new Date(last).toISOString()}" title="${escape(stamp(last))}">${escape(time(last))}</time><small>${escape(ago(last,now))}</small>`:'No check-in or checkout yet'}</dd></div></dl>${info.condition==='out_of_service'?`<p class="scanner-reason-preview"><b>Issue:</b> ${escape(info.device?.outOfServiceReason||'Reason not available')}</p>`:''}${actionButton(action.type,id,action.label,`btn ${action.type==='check_out'?'':'secondary'} scanner-primary-action`)}</article>`;
  }
  function list(state,ids){return `<div class="scanner-table-shell card"><table class="scanner-table"><caption class="sr-only">Scanner equipment status</caption><thead><tr><th>Scanner</th><th>Status</th><th>Current / last person</th><th>Last check-in or checkout</th><th>Location</th><th><span class="sr-only">Action</span></th></tr></thead><tbody>${ids.map(id=>{const info=facts(state,id),action=primaryAction(state,info),last=info.device?.lastCustodyAt;return `<tr class="${info.overdue?'scanner-overdue-row':''}"><td data-label="Scanner"><button type="button" class="plain-link scanner-table-id" data-scanner-action="device" data-scanner-id="${id}">${escape(info.meta.label)}</button>${info.meta.label!==id?`<small>${id}</small>`:''}</td><td data-label="Status">${statusBadge(info)}${info.overdue?'<small class="scanner-overdue-text">Over 12 hours</small>':''}</td><td data-label="Current / last person">${escape(info.holder)}</td><td data-label="Last custody action">${last?`${escape(ACTIONS[info.device.lastCustodyAction]||'Updated')}<small>${escape(stamp(last))} · ${escape(ago(last,nowOf(state)))}</small>`:'No action recorded'}</td><td data-label="Location">${escape(info.location)}</td><td class="scanner-table-action">${actionButton(action.type,id,action.label,'btn secondary small')}</td></tr>`;}).join('')}</tbody></table></div>`;}
  function board(state){
    const entries=IDS.map(id=>facts(state,id)),counts={available:0,out:0,service:0,unconfirmed:0,overdue:0};entries.forEach(info=>{counts[info.status]++;if(info.overdue)counts.overdue++;});
    const mine=entries.filter(info=>info.device?.holderUid===state.user.uid&&info.checkout==='checked_out');
    const result=entries.filter(info=>(filter==='all'||filter==='overdue'&&info.overdue||info.status===filter)&&(!search||[info.id,info.meta.label,info.holder,info.location].some(value=>String(value).toLowerCase().includes(search.toLowerCase())))).map(info=>info.id);
    return `${mine.length?`<section class="scanner-mine"><b>Your checked-out ${mine.length===1?'scanner':'scanners'}</b><div>${mine.map(info=>`<button type="button" data-scanner-action="device" data-scanner-id="${info.id}">${escape(info.meta.label)} <span>${escape(duration(nowOf(state)-info.device.checkedOutAt))}</span></button>`).join('')}</div></section>`:''}<section class="scanner-summary" aria-label="Fleet totals">${[['available','Available'],['out','Checked out'],['service','Out of service'],['unconfirmed','Unconfirmed'],['overdue','Over 12 hrs']].map(([key,label])=>`<button type="button" class="scanner-summary-item ${filter===key?'active':''} scanner-summary-${key}" data-scanner-action="filter" data-scanner-value="${key}" aria-pressed="${filter===key}"><b>${counts[key]}</b><span>${label}</span></button>`).join('')}</section><div class="scanner-board-tools"><label class="scanner-search"><span class="sr-only">Search scanners, people, or locations</span><input type="search" placeholder="Search scanner, person, or location" value="${escape(search)}" data-scanner-field="search"></label><div class="view-toggle" role="group" aria-label="Scanners view"><button type="button" data-scanner-action="layout" data-scanner-value="grid" aria-pressed="${layout==='grid'}" class="${layout==='grid'?'active':''}">${icon('grid')}Cards</button><button type="button" data-scanner-action="layout" data-scanner-value="list" aria-pressed="${layout==='list'}" class="${layout==='list'?'active':''}">${icon('list')}List</button></div></div><div class="scanner-result-caption"><span>${result.length} of 20 scanners${filter!=='all'?` · ${escape({available:'Available',out:'Checked out',service:'Out of service',unconfirmed:'Unconfirmed',overdue:'Over 12 hours'}[filter])}`:''}</span>${filter!=='all'||search?'<button type="button" data-scanner-action="clear">Show all</button>':''}</div>${result.length?layout==='list'?list(state,result):`<section class="scanner-grid" aria-label="Scanner inventory">${result.map(id=>card(state,id)).join('')}</section>`:'<div class="empty-state card">No scanners match these filters.</div>'}<p class="scanner-footnote">An unconfirmed scanner needs its first physical check-in. Overdue notices appear for Leads, Supervisors, Managers, and Master when an authorized app is open.</p>`;
  }
  function actionOptions(state,info){
    if(!has(state,'scanner.use')||state.scannerSetupRequired)return '';
    const result=[];
    if(info.status==='available')result.push(actionButton('check_out',info.id,'Check out','btn'));
    if(info.checkout==='unconfirmed'||info.checkout==='checked_out'&&(info.device?.holderUid===state.user.uid||has(state,'scanner.manage')))result.push(actionButton('check_in',info.id,info.checkout==='unconfirmed'?'Confirm check-in':'Check in','btn'));
    result.push(actionButton('out_of_service',info.id,info.condition==='out_of_service'?'Update service issue':'Report out of service','btn secondary'));
    if(info.condition==='out_of_service'&&has(state,'scanner.manage'))result.push(actionButton('return_to_service',info.id,'Return to service','btn secondary'));
    if(info.device&&(info.checkout!=='checked_out'||info.device.holderUid===state.user.uid||has(state,'scanner.manage')))result.push(actionButton('update_location',info.id,'Update location','btn secondary'));
    return `<div class="scanner-device-actions">${result.join('')}</div>`;
  }
  function eventCard(state,event){
    const action=event.action||event.lastAction,who=event.actorName||event.updatedByName||'Team member',role=publicRoleName('',event.actorRole||event.updatedByRole||''),custodian=event.checkoutStatus==='checked_out'?event.holderName:event.lastHolderName;
    return `<article class="scanner-event"><div class="scanner-event-top"><b>${escape(ACTIONS[action]||action||'Equipment update')}</b><time datetime="${new Date(eventTime(event)).toISOString()}">${escape(stamp(eventTime(event)))}</time></div><p>${escape(who)}${role?` <span>· ${escape(role)}</span>`:''}</p><dl><div><dt>Scanner</dt><dd><button type="button" class="plain-link" data-scanner-action="device" data-scanner-id="${escape(event.scannerId)}">${escape(event.scannerLabel||inventory(state,event.scannerId).label)}</button>${event.scannerLabel&&event.scannerLabel!==event.scannerId?` <small>${escape(event.scannerId)}</small>`:''}</dd></div><div><dt>Person</dt><dd>${escape(custodian||'No checkout recorded')}</dd></div><div><dt>Location</dt><dd>${escape(event.location||'Not recorded')}</dd></div><div><dt>Condition</dt><dd>${event.condition==='out_of_service'?'Out of service':event.condition==='good'?'Good':'Unconfirmed'}</dd></div></dl>${event.outOfServiceReason?`<p class="scanner-event-reason"><b>Reason:</b> ${escape(event.outOfServiceReason)}</p>`:''}${event.note?`<p class="scanner-event-note">${escape(event.note)}</p>`:''}<details class="scanner-event-audit"><summary>Record details</summary><p>Stable scanner ID: ${escape(event.scannerId)}<br>Event: ${escape(event.id||event.auditId)} · Revision ${escape(event.revision)}<br>Actor UID: ${escape(event.actorUid||event.updatedBy)}<br>Previous state: ${escape(event.previousCheckoutStatus||'unconfirmed')} · ${escape(event.previousCondition||'unconfirmed')}<br>Previous location: ${escape(event.previousLocation||'Not recorded')}${event.previousHolderName?`<br>Previous custodian: ${escape(event.previousHolderName)}`:''}</p></details></article>`;
  }
  function detail(state,id){
    const info=facts(state,id),all=history(state,id),events=detailTab==='service'?all.filter(serviceEvent):all;
    return `<button type="button" class="scanner-back" data-scanner-action="board">← All scanners</button><section class="scanner-device-summary card"><div class="scanner-device-heading"><div class="scanner-glyph">${scannerGlyph()}</div><div><span class="eyebrow">Equipment record</span><h2>${escape(info.meta.label)}</h2><p>${id}${info.meta.homeLocation?` · Home: ${escape(info.meta.homeLocation)}`:''}</p></div>${statusBadge(info)}</div>${info.overdue?`<div class="scanner-overdue-notice"><b>Checked out for ${escape(duration(nowOf(state)-info.device.checkedOutAt))}</b><span>The 12-hour return window has been exceeded.</span></div>`:''}<dl class="scanner-detail-facts"><div><dt>${info.checkout==='checked_out'?'Currently with':'Last checked out by'}</dt><dd>${escape(info.holder)}</dd></div><div><dt>Location</dt><dd>${escape(info.location)}</dd></div><div><dt>Condition</dt><dd>${info.condition==='good'?'Good':info.condition==='out_of_service'?'Out of service':'Not yet confirmed'}</dd></div><div><dt>Last check-in or checkout</dt><dd>${info.device?.lastCustodyAt?`${escape(ACTIONS[info.device.lastCustodyAction]||'Updated')}<small>${escape(stamp(info.device.lastCustodyAt))} · ${escape(ago(info.device.lastCustodyAt,nowOf(state)))}</small>`:'No custody action recorded'}</dd></div>${info.device?.updatedAt?`<div><dt>Latest equipment update</dt><dd>${escape(ACTIONS[info.device.lastAction]||'Updated')}<small>${escape(stamp(info.device.updatedAt))} · ${escape(info.device.updatedByName||'')}</small></dd></div>`:''}</dl>${info.condition==='out_of_service'?`<div class="scanner-service-reason"><b>Out-of-service reason</b><p>${escape(info.device?.outOfServiceReason||'Reason not recorded')}</p></div>`:''}${actionOptions(state,info)}${!has(state,'scanner.use')?'<p class="field-note">Your account can view scanner records. Master can assign equipment permissions in Team.</p>':''}</section><div class="scanner-detail-tabs" role="group" aria-label="Scanner history"><button type="button" data-scanner-action="detail-tab" data-scanner-value="activity" class="${detailTab==='activity'?'active':''}" aria-pressed="${detailTab==='activity'}">Check-in / checkout & activity <span>${all.length}</span></button><button type="button" data-scanner-action="detail-tab" data-scanner-value="service" class="${detailTab==='service'?'active':''}" aria-pressed="${detailTab==='service'}">Out-of-service history <span>${all.filter(serviceEvent).length}</span></button></div><section class="scanner-history card"><div class="scanner-history-heading"><h3>${detailTab==='service'?'Service history':'Equipment history'}</h3><span>${events.length} ${events.length===1?'record':'records'}</span></div><p class="field-note">Permanent equipment records. Times are shown in Pacific time.</p>${events.length?events.slice(0,detailLimit).map(event=>eventCard(state,event)).join(''):'<div class="empty-state">No '+(detailTab==='service'?'service events':'equipment actions')+' recorded for this scanner.</div>'}${events.length>detailLimit?`<button type="button" class="btn secondary scanner-load-more" data-scanner-action="detail-more">Show next ${Math.min(50,events.length-detailLimit)} records</button>`:''}</section>`;
  }
  function peopleOptions(state){
    const names=new Map(Object.values(state.users||{}).map(person=>[person.uid,person.displayName]));
    for(const event of allHistory(state))for(const [uid,name] of [[event.actorUid,event.actorName],[event.holderUid,event.holderName],[event.lastHolderUid,event.lastHolderName]])if(uid&&!names.has(uid))names.set(uid,name||uid);
    return [...names].sort((a,b)=>String(a[1]).localeCompare(String(b[1])));
  }
  function filteredLog(state){
    if(logStart&&logEnd&&logStart>logEnd)return [];
    return allHistory(state).filter(event=>(!logScanner||event.scannerId===logScanner)&&(!logPerson||[event.actorUid,event.updatedBy,event.holderUid,event.lastHolderUid,event.previousHolderUid].includes(logPerson))&&(!logAction||(logAction==='service'?serviceEvent(event):(event.action||event.lastAction)===logAction))&&(!logStart||pacificDate(eventTime(event))>=logStart)&&(!logEnd||pacificDate(eventTime(event))<=logEnd));
  }
  function logView(state){const events=filteredLog(state),invalid=logStart&&logEnd&&logStart>logEnd;return `<section class="scanner-log-heading"><div><h2>Complete equipment log</h2><p>Find records by scanner, person, action, or Pacific calendar date.</p></div><button type="button" class="btn secondary" data-scanner-action="export" ${!events.length||invalid?'disabled':''}>Export filtered CSV</button></section><form class="scanner-log-filters card" aria-label="Equipment log filters"><label>Scanner<select data-scanner-field="logScanner"><option value="">All scanners</option>${IDS.map(id=>`<option value="${id}" ${id===logScanner?'selected':''}>${escape(inventory(state,id).label)}${inventory(state,id).label!==id?' ('+id+')':''}</option>`).join('')}</select></label><label>Person <span class="field-note">Actor or custodian</span><select data-scanner-field="logPerson"><option value="">All people</option>${peopleOptions(state).map(([uid,name])=>`<option value="${escape(uid)}" ${uid===logPerson?'selected':''}>${escape(name)}</option>`).join('')}</select></label><label>Action<select data-scanner-field="logAction"><option value="">All actions</option>${Object.entries(ACTIONS).map(([id,label])=>`<option value="${id}" ${id===logAction?'selected':''}>${label}</option>`).join('')}<option value="service" ${logAction==='service'?'selected':''}>All service history</option></select></label><label>From date<input type="date" data-scanner-field="logStart" value="${escape(logStart)}"></label><label>Through date<input type="date" data-scanner-field="logEnd" value="${escape(logEnd)}"></label><button type="button" class="btn quiet" data-scanner-action="reset-log">Clear filters</button></form>${invalid?'<div class="error" role="alert">Choose a through date on or after the from date.</div>':''}<section class="scanner-history card"><div class="scanner-history-heading"><h3>${events.length} matching ${events.length===1?'record':'records'}</h3><span>All saved history</span></div>${events.length?events.slice(0,logLimit).map(event=>eventCard(state,event)).join(''):`<div class="empty-state">${allHistory(state).length?'No records match these filters.':'No scanner actions have been recorded yet.'}</div>`}${events.length>logLimit?`<button type="button" class="btn secondary scanner-load-more" data-scanner-action="log-more">Show next ${Math.min(50,events.length-logLimit)} records</button>`:''}</section>`;}
  function inventoryView(state){if(!master(state))return '<div class="empty-state card">Master manages scanner names and home locations.</div>';return `<section class="scanner-log-heading"><div><h2>Manage scanner fleet</h2><p>Set the names your team recognizes. Stable IDs and past records are retained.</p></div><button type="button" class="btn secondary" data-scanner-action="install-roles">Enable / update scanner roles</button></section><div class="scanner-inventory-help card"><b>20 equipment records</b><p>Home location is the suggested return location. Changing a name does not change historical labels or the equipment key.</p></div><section class="scanner-inventory-list">${IDS.map(id=>{const meta=inventory(state,id),draft=drafts.get(id)||meta;return `<form class="scanner-inventory-form card" data-scanner-config="${id}"><div class="scanner-inventory-key"><span class="scanner-glyph">${scannerGlyph()}</span><b>${id}</b></div><label>Scanner name / ID<input name="label" value="${escape(draft.label)}" required maxlength="40" autocomplete="off"></label><label>Home / return location<input name="homeLocation" value="${escape(draft.homeLocation)}" maxlength="80" autocomplete="off" placeholder="e.g. Scanner charging station"></label><button type="submit" class="btn secondary" ${!state.connected||state.scannerSetupRequired?'disabled':''}>Save scanner</button><div class="scanner-config-status" role="status"></div></form>`;}).join('')}</section>`;}
  function render(state){
    const content=!state.user?gate(state):view==='device'&&selectedId?detail(state,selectedId):view==='log'?logView(state):view==='inventory'?inventoryView(state):board(state);
    return `<div id="scanner-workspace">${heading(state)}${state.user?`${tabs(state)}${setupNotice(state)}${rolesNeedSetup(state)?'<div class="scanner-role-setup"><span>Enable equipment permissions for your standard team roles.</span><button type="button" class="btn secondary small" data-scanner-action="install-roles">Enable scanner roles</button></div>':''}`:''}${content}</div>`;
  }
  function showFormError(d,message){const target=d.querySelector('.scanner-form-error');target.textContent=message;target.hidden=false;}
  function openAction(id,action){
    if(!requireUser()||!IDS.includes(id))return;const state=getState(),info=facts(state,id),person=state.user;
    if(!has(state,'scanner.use')||state.scannerSetupRequired)return toast('Your account cannot update scanner equipment yet.');
    if(action==='return_to_service'&&!has(state,'scanner.manage'))return toast('A Lead, Supervisor, Manager, or Master must return this scanner to service.');
    const expectedRevision=info.device?.revision||0,initial=info.checkout==='unconfirmed'&&action==='check_in',isCheckIn=action==='check_in',isIssue=action==='out_of_service',isRepair=action==='return_to_service';
    const condition=info.condition==='out_of_service'?'out_of_service':'good',canRestore=has(state,'scanner.manage'),location=(action==='check_in'?info.meta.homeLocation:'')||info.device?.location||info.meta.homeLocation||'';
    const title=initial?'Confirm scanner check-in':ACTION_TITLES[action];
    const d=dialog(title,`<form class="scanner-action-form" data-uid="${escape(person.uid)}" data-scanner-id="${id}" data-revision="${expectedRevision}"><div class="scanner-action-scroll"><div class="scanner-action-device"><span class="scanner-glyph">${scannerGlyph()}</span><div><h3>${escape(info.meta.label)}</h3><p>${id}${info.meta.label!==id?' · Stable equipment ID':''}</p></div>${statusBadge(info)}</div><div class="scanner-actor-note"><span>Recorded automatically as</span><b>${escape(person.displayName)}</b><small>${escape(roleLabel(person))}</small></div>${info.checkout==='checked_out'?`<p class="scanner-custody-note">Currently with <b>${escape(info.device?.holderName||'Unknown person')}</b> since ${escape(stamp(info.device?.checkedOutAt))}.</p>`:''}${initial?'<p class="setup-note">Confirm the scanner is physically here before saving its first check-in.</p>':''}${isIssue&&info.checkout==='checked_out'?'<p class="setup-note">Reporting a service issue keeps the current checkout open. Check the scanner in when it is physically returned.</p>':''}<label for="scanner-location">${isCheckIn?'Return location':'Location'}</label><input id="scanner-location" name="location" value="${escape(location)}" required maxlength="80" autocomplete="off" placeholder="Work area or charging station" list="scanner-home-locations"><datalist id="scanner-home-locations">${[...new Set(IDS.map(key=>inventory(state,key).homeLocation).filter(Boolean))].map(value=>`<option value="${escape(value)}"></option>`).join('')}</datalist>${isCheckIn?`<label for="scanner-condition">Condition on return</label><select id="scanner-condition" name="condition"><option value="good" ${condition==='good'?'selected':''} ${info.condition==='out_of_service'&&!canRestore?'disabled':''}>Good</option><option value="out_of_service" ${condition==='out_of_service'?'selected':''}>Out of service</option></select>${info.condition==='out_of_service'&&!canRestore?'<p class="field-note">This scanner stays out of service until someone with equipment management permission clears it.</p>':''}`:''}${isCheckIn||isIssue?`<div class="scanner-reason-field" ${!isIssue&&condition!=='out_of_service'?'hidden':''}><label for="scanner-reason">Out-of-service reason <span class="scanner-required">Required</span></label><textarea id="scanner-reason" name="reason" maxlength="500" ${isIssue||condition==='out_of_service'?'required':''} rows="3" placeholder="Describe the fault so the next person can act">${escape(info.condition==='out_of_service'?info.device?.outOfServiceReason||'':'')}</textarea></div>`:''}<label for="scanner-note">${isRepair?'Repair / resolution note <span class="scanner-required">Required</span>':'Update note <span class="muted">(optional)</span>'}</label><textarea id="scanner-note" name="note" maxlength="500" rows="3" ${isRepair?'required':''} placeholder="${isRepair?'What was repaired or checked before returning to service?':'Anything the next person should know'}"></textarea><p class="field-note">The saved record includes scanner identity, person, assigned role, date, time, condition, location, and the action.</p></div><div class="scanner-action-footer"><p class="scanner-form-error error" role="alert" hidden></p><p class="scanner-action-stale field-note" role="status" hidden></p><div class="form-actions"><button type="button" class="btn secondary scanner-cancel">Cancel</button><button type="submit" class="btn" ${!state.connected?'disabled':''}>${isRepair?'Return to service':isIssue?'Save service issue':action==='update_location'?'Save location':initial?'Confirm check-in':isCheckIn?'Save check-in':'Check out scanner'}</button></div></div></form>`);
    fitActionDialog?.(d,'scanner-action-dialog');
    const form=d.querySelector('form'),submit=form.querySelector('button[type=submit]'),buttonLabel=submit.textContent;
    d.querySelector('.scanner-cancel').onclick=()=>d.close();
    const refreshReason=()=>{if(!isCheckIn)return;const shown=form.elements.condition.value==='out_of_service';form.querySelector('.scanner-reason-field').hidden=!shown;form.elements.reason.required=shown;};
    if(isCheckIn)form.elements.condition.onchange=refreshReason;
    form.onsubmit=async event=>{
      event.preventDefault();if(form.dataset.uid!==getState().user?.uid)return showFormError(d,'Your account changed. Close this form and sign in again.');
      const fields=new FormData(form),payload={scannerId:id,action,expectedRevision,location:String(fields.get('location')||'').trim(),note:String(fields.get('note')||'').trim()};
      if(isCheckIn)payload.condition=fields.get('condition');if(isIssue||isCheckIn&&payload.condition==='out_of_service')payload.reason=String(fields.get('reason')||'').trim();
      if(!payload.location)return showFormError(d,'Enter the scanner location.');if((isIssue||payload.condition==='out_of_service')&&!payload.reason)return showFormError(d,'Enter the reason the scanner is out of service.');if(isRepair&&!payload.note)return showFormError(d,'Enter the repair or resolution note.');
      form.dataset.busy='true';submit.disabled=true;submit.textContent='Saving…';form.querySelector('.scanner-form-error').hidden=true;
      try{await getPlatform().updateScanner(payload);d.close();toast(`${info.meta.label} · ${ACTIONS[action]||'Updated'}`);}
      catch(error){if(d.isConnected)showFormError(d,error.message||'The scanner update could not be saved.');}
      finally{if(d.isConnected){form.dataset.busy='false';submit.textContent=buttonLabel;refreshOpenDialog(getState());}}
    };
  }
  function refreshOpenDialog(state){
    const form=document.querySelector('.scanner-action-form');if(!form)return;
    if(!state.user||form.dataset.uid!==state.user.uid){form.closest('dialog')?.close();return;}
    const stale=(current(state,form.dataset.scannerId)?.revision||0)!==Number(form.dataset.revision),note=form.querySelector('.scanner-action-stale');
    note.hidden=!stale&&state.connected;note.textContent=stale?'This scanner changed while the form was open. Close it and review the latest record before saving.':'Connection interrupted. Reconnect before saving.';
    form.querySelector('button[type=submit]').disabled=form.dataset.busy==='true'||stale||!state.connected||state.scannerSetupRequired;
  }
  function exportCsv(state){
    const events=filteredLog(state);if(!events.length)return;
    const rows=[['Event ID','Stable scanner ID','Scanner label at event','Action','Pacific date and time','UTC timestamp','Actor','Actor UID','Actor role','Checkout status','Current custodian','Custodian UID','Last custodian','Condition','Location','Out-of-service reason','Note','Previous checkout status','Previous condition','Previous location','Revision'],...events.map(event=>[event.id||event.auditId,event.scannerId,event.scannerLabel||event.scannerId,ACTIONS[event.action||event.lastAction]||event.action,stamp(eventTime(event)),new Date(eventTime(event)).toISOString(),event.actorName||event.updatedByName,event.actorUid||event.updatedBy,event.actorRole||event.updatedByRole,event.checkoutStatus,event.holderName,event.holderUid,event.lastHolderName,event.condition,event.location,event.outOfServiceReason,event.note,event.previousCheckoutStatus,event.previousCondition,event.previousLocation,event.revision])];
    const cell=value=>{let text=String(value??'');if(/^[\s]*[=+\-@]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';};
    const blob=new Blob(['\uFEFF'+rows.map(row=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=`Suja_Scanner_Log_${pacificDate(nowOf(state))}.csv`;document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`${events.length} equipment records exported`);
  }
  async function installRoles(button){button.disabled=true;button.textContent='Updating roles…';try{await getPlatform().installScannerRoles();toast('Scanner permissions are ready. Review team assignments in Team.');}catch(error){toast(error.message||'Scanner roles could not be updated.');}finally{if(button.isConnected){button.disabled=false;button.textContent='Enable / update scanner roles';}}}
  function afterRender(state){
    refreshOpenDialog(state);const wrapper=document.getElementById('scanner-workspace');if(!wrapper||wrapper.dataset.scannerBound==='true')return;wrapper.dataset.scannerBound='true';
    wrapper.addEventListener('click',event=>{const button=event.target.closest('[data-scanner-action]');if(!button||!wrapper.contains(button))return;event.preventDefault();const action=button.dataset.scannerAction,id=button.dataset.scannerId,value=button.dataset.scannerValue;
      if(action==='signin'){requireUser();return;}if(action==='device'){route('device',id);return;}if(['board','log','inventory'].includes(action)){route(action);return;}if(action==='layout'){layout=value==='list'?'list':'grid';try{localStorage.setItem('sujaTools.view.scanner',layout);}catch{}redraw();return;}if(action==='filter'){filter=value===filter?'all':value;redraw();return;}if(action==='clear'){filter='all';search='';redraw();return;}if(action==='detail-tab'){detailTab=value==='service'?'service':'activity';detailLimit=50;redraw();return;}if(action==='detail-more'){detailLimit+=50;redraw();return;}if(action==='log-more'){logLimit+=50;redraw();return;}if(action==='reset-log'){logScanner=logPerson=logAction=logStart=logEnd='';logLimit=50;redraw();return;}if(action==='export'){exportCsv(getState());return;}if(action==='install-roles'){void installRoles(button);return;}if(Object.hasOwn(ACTIONS,action))openAction(id,action);
    });
    const setField=event=>{const field=event.target.dataset.scannerField;if(!field)return;const value=event.target.value;
      if(field==='search')search=value;else if(field==='logScanner')logScanner=value;else if(field==='logPerson')logPerson=value;else if(field==='logAction')logAction=value;else if(field==='logStart')logStart=value;else if(field==='logEnd')logEnd=value;logLimit=50;redraw();
    };
    wrapper.querySelectorAll('[data-scanner-field]').forEach(input=>input.addEventListener(input.tagName==='SELECT'||input.type==='date'?'change':'input',setField));
    wrapper.querySelectorAll('[data-scanner-config]').forEach(form=>{
      form.oninput=()=>drafts.set(form.dataset.scannerConfig,{label:form.elements.label.value,homeLocation:form.elements.homeLocation.value});
      form.onsubmit=async event=>{event.preventDefault();if(!master(getState()))return;const id=form.dataset.scannerConfig,label=form.elements.label.value.trim(),homeLocation=form.elements.homeLocation.value.trim(),status=form.querySelector('.scanner-config-status'),button=form.querySelector('button');
        if(!label){status.textContent='Enter a scanner name.';return;}if(IDS.some(other=>other!==id&&inventory(getState(),other).label.toLowerCase()===label.toLowerCase())){status.textContent='Use a unique scanner name so the team can identify this device.';return;}
        button.disabled=true;status.textContent='Saving…';try{await getPlatform().configureScanner({scannerId:id,label,homeLocation});drafts.delete(id);if(form.isConnected)status.textContent='Scanner saved.';toast(`${label} saved`);}catch(error){if(form.isConnected)status.textContent=error.message||'Could not save this scanner.';}finally{if(button.isConnected)button.disabled=!getState().connected;}
      };
    });
    wrapper.querySelector('.scanner-log-filters')?.addEventListener('submit',event=>event.preventDefault());
  }
  const onHash=()=>{readRoute();redraw();};
  readRoute();window.addEventListener('hashchange',onHash);
  return {render,afterRender,destroy(){destroyed=true;window.removeEventListener('hashchange',onHash);document.querySelector('.scanner-action-form')?.closest('dialog')?.close();drafts.clear();}};
}
